import { defineConfig, type Options } from 'tsup';
import { withIifeExternalPlugin } from '../../iifeExternalPlugin.js';

function options(prefix: string, minify: boolean): Options {
    return withIifeExternalPlugin({
        '@preserves/core': 'Preserves',
    }, {
        entry: {
            [prefix]: 'src/index.ts',
        },
        format: ['cjs', 'esm', 'iife'],
        outExtension({ format }) {
            switch (format) {
                case 'cjs': return { js: '.cjs' };
                case 'esm': return { js: '.mjs' };
                case 'iife': return { js: '.js' };
            }
        },
        globalName: 'Syndicate',
        sourcemap: true,
        clean: true,
        minify,
        target: 'es2017',
    });
}

export default defineConfig([options('syndicate', false), options('syndicate.min', true)]);
